      "title": "Cenerentola",
      "original_title": "Cinderella",
      "overview": "Ella cresce felice tra mamma e pap\u00e0. Ma la sua serenit\u00e0 \u00e8 turbata dalla morte prematura della madre, che le ha fatto promettere di essere sempre coraggiosa e gentile. Coraggio e gentilezza le serviranno con la donna che il padre sposer\u00e0 in seconde nozze. Lady Tremaine ha un ex principe da dimenticare e due figlie da accasare. Sola e vessata, dopo la perdita del padre, Ella \u00e8 costretta a (ri)governare la casa e ad abitare la sua ala polverosa. Appellata Cinderella dalle due sorellastre, Ella fugge a cavallo dove incontra Kit, un ragazzo che lavora a palazzo. Emozionata da quell'incontro, decide di partecipare al ballo reale e aperto a sorpresa ai sudditi. Il suo desiderio non ha per\u00f2 fatto i conti con la matrigna e le sorellastre, che la umiliano strappandole il vestito. Ma lass\u00f9 qualcuno la ama. Avvicinata dalla fata madrina, i suoi sogni diventano realt\u00e0. Dentro una zucca trasformata in carrozza, raggiunger\u00e0 il castello e scoprir\u00e0 che Kit \u00e8 addirittura un principe. Il suo principe.",
