      "title": "Come d'incanto",
      "original_title": "Enchanted",
      "overview": "C'era una volta in un bosco \"animato\" una principessa in attesa del suo principe, un principe impaziente di baciare una principessa, una matrigna determinata a impedire il loro incontro. Il destino decide altrimenti e i due giovani si trovano e si innamorano. Deciso a sposarla, Edward conduce Giselle al castello ma la regina malvagia, con un inganno, la spinge in un pozzo profondo verso un mondo senza lieto fine. Scaraventata nella realt\u00e0 e spaventata dal traffico di New York, Giselle trova rifugio nel castello di un cartellone pubblicitario. In suo aiuto accorre Robert, un avvocato divorzista che non crede alle favole ma che finir\u00e0 per vivere \"felice e contento\".",
