      "overview": "Peter, Edmund, Susan e Lucy a un anno di distanza frequentano la scuola nella Gran Bretagna impegnata nella Seconda Guerra Mondiale. Un giorno il richiamo del corno li proietta nuovamente nel mondo magico che ben conoscono o, meglio, che credono di conoscere. Perch\u00e9 un anno dei nostri equivale a milletrecento anni in quelle terre in cui, nel frattempo, tutti gli abitanti di Narnia sono stati uccisi o costretti a nascondersi a causa dell'invasione del popolo dei Telmarini. I quali in questo momento avrebbero un legittimo erede al trono, il principe Caspian, il quale \u00e8 costretto alla fuga perch\u00e9 lo zio, Lord Miraz, vuole ucciderlo per conquistare il potere da cedere in futuro al suo primogenito appena nato. I quattro fratelli Pevensie, aiutati dai sopravvissuti discendenti degli abitanti di Narnia, si mettono in azione per contrastare Miraz e i suoi uomini. Ma non c'\u00e8 pi\u00f9 il leone Aslan al loro fianco o, perlomeno, non lo si vede.",
